// MongoDB Node.js Driver
const { MongoClient } = require('mongodb')
const client = new MongoClient('mongodb://localhost:27017')

await client.connect()
const db = client.db('myapp')
const users = db.collection('users')

// 增
await users.insertOne({ name: '张三', age: 25 })
await users.insertMany([
  { name: '李四', age: 30 },
  { name: '王五', age: 22 }
])

// 查
const all = await users.find().toArray()
const young = await users.find({ age: { $lt: 25 } }).toArray()

// 改
await users.updateOne({ name: '张三' }, { $set: { age: 26 } })

// 删
await users.deleteOne({ name: '王五' })

// 聚合（类似 SQL GROUP BY）
const result = await users.aggregate([
  { $group: { _id: null, avgAge: { $avg: '$age' } } }
]).toArray()

console.log('平均年龄:', result[0].avgAge)

// Node.js 使用 Redis (ioredis)
const Redis = require('ioredis')
const redis = new Redis()

// String — 缓存
await redis.set('user:1', JSON.stringify({ name: '张三', age: 25 }))
await redis.expire('user:1', 3600) // 1小时过期
const user = JSON.parse(await redis.get('user:1'))

// Hash — 存储对象字段
await redis.hset('user:2', 'name', '李四', 'age', '30')
const name = await redis.hget('user:2', 'name')

// Sorted Set — 排行榜
await redis.zadd('leaderboard', 100, '张三')
await redis.zadd('leaderboard', 200, '李四')
await redis.zadd('leaderboard', 150, '王五')
// 获取 Top 3
const top3 = await redis.zrevrange('leaderboard', 0, 2, 'WITHSCORES')
// → ['李四','200','王五','150','张三','100']

// Set — 标签/去重
await redis.sadd('tags:article:1', 'JavaScript', 'Vue', '前端')
const tags = await redis.smembers('tags:article:1')
